[
  { "key": "ctrl+alt+t", "command": "workbench.action.terminal.new" },
  { "key": "ctrl+enter", "command": "markdown.showPreviewToSide",
    "when": "editorTextFocus && editorLangId == 'markdown'" },
  { "key": "ctrl+shift+k", "command": "-editor.action.deleteLines" }
]
