// src/extension.ts  (package.json contributes command "wc.count", title "Count Words")
import * as vscode from 'vscode';

export function activate(context: vscode.ExtensionContext) {
  const cmd = vscode.commands.registerCommand('wc.count', () => {
    const editor = vscode.window.activeTextEditor;
    if (!editor) {
      vscode.window.showWarningMessage('No active editor');
      return;
    }
    const sel = editor.selection;
    const text = editor.document.getText(sel.isEmpty ? undefined : sel);
    const words = text.split(/\s+/).filter(Boolean).length;
    vscode.window.showInformationMessage(`Words: ${words}`);
  });
  context.subscriptions.push(cmd);
}

export function deactivate() {}
